"""Pre-seed Rasa trackers before a Coval voice simulation connects."""

from __future__ import annotations

from pathlib import Path
from typing import Optional

import aiohttp

from rasa.builder.copilot.mcp_server.tools.coval.manifest import VoiceRunManifestEntry
from rasa.builder.copilot.mcp_server.tools.evaluate_agent import (
    _set_initial_slots,
    _trigger_session_start,
)
from rasa.builder.copilot.mcp_server.tools.scenario_initial_setup import (
    load_project_memory_schema,
    partition_initial_slots,
)


async def preseed_voice_run_entry(
    session: aiohttp.ClientSession,
    entry: VoiceRunManifestEntry,
    rasa_url: str,
    *,
    project_path: Optional[Path] = None,
) -> None:
    """Inject ``initial_slots`` for one manifest entry before Coval dials in.

    Project fields marked ``seed: true`` in ``memory.yml`` are sent on
    ``/session_start`` metadata when ``project_path`` is provided. Remaining
    slots are written via the tracker events API. The voice channel may still
    run its own session start on connect; text-style pre-seeding mirrors the
    eval runner ordering when seed metadata is present.
    """
    initial_slots = dict(entry.initial_slots)
    session_start_metadata: dict = {}
    post_session_start_slots = initial_slots
    if project_path is not None:
        project_memory = load_project_memory_schema(project_path)
        session_start_metadata, post_session_start_slots = partition_initial_slots(
            initial_slots, project_memory
        )
    if session_start_metadata:
        await _trigger_session_start(
            session,
            entry.rasa_sender_id,
            rasa_url,
            session_start_metadata=session_start_metadata,
        )
    await _set_initial_slots(
        session,
        entry.rasa_sender_id,
        post_session_start_slots,
        rasa_url,
    )


async def preseed_voice_run_manifest(
    entries: list[VoiceRunManifestEntry],
    rasa_url: str,
    *,
    project_path: Optional[Path] = None,
    session: Optional[aiohttp.ClientSession] = None,
) -> None:
    """Pre-seed every entry in a voice run manifest."""
    if session is not None:
        for entry in entries:
            await preseed_voice_run_entry(
                session, entry, rasa_url, project_path=project_path
            )
        return

    async with aiohttp.ClientSession() as owned_session:
        for entry in entries:
            await preseed_voice_run_entry(
                owned_session, entry, rasa_url, project_path=project_path
            )
